	public static void Main(Args _args)
    {
        JISBookInventoryUpdationController controller = JISBookInventoryUpdationController::Construct();

        controller.initFromBookFormIfNeeded(_args);

        if(controller.prompt())
        {
            controller.runOperation();
        }
    }

protected void new(IdentifierName _className = '', 
    IdentifierName _methodName = '', 
    SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Asynchronous)
{
    super(_className, _methodName, _executionMode);
}

public void initFromBookFormIfNeeded(Args _args)
{
    FormRun callerFormRun = _args.caller();

    if (callerFormRun
        && callerFormRun.name() == formStr(JISBook))
    {
        //recupera el registro activo del formulario
        JISBookTable bookActiveRecord = callerFormRun
            .dataSource(formDataSourceStr(JISBook, JISBookTable))
            .cursor();

        JISBookInventoryUpdationDataContract contract = this.getDatacontract();

        contract.parmBookId(bookActiveRecord.Id);
    }
}

public static JISBookInventoryUpdationController Construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Asynchronous)
{
    JISBookInventoryUpdationController controller =  new JISBookInventoryUpdationController(classStr(JISBookInventoryUpdationService),
        methodStr(JISBookInventoryUpdationService, runProcess),
        _executionMode);

    controller.parmDialogCaption("@ITFormacion:UpdateBookInventory");

    return controller;
}

public boolean validateParameters()
{
    boolean ret = super();

    if (ret)
    {
        JISBookInventoryUpdationDataContract dataContract = this.getDatacontract();
        ret = this.validateBook(dataContract.parmBookId()) 
            && this.validateNewQty(dataContract.parmNewQty());
    }

    return ret;
}

public boolean validateBook(JISId _bookId)
{
    if (!JISBookTable::exist(_bookId))
    {
        return checkFailed(strFmt("@ITFormacion:Book1DoesNotExists", _bookId));
    }

    return true;
}

public boolean validateNewQty(Qty _newQty)
{
    if (_newQty < 0)
    {
        return checkfailed("@ITFormacion:TransactionWouldMakeTheTotalNegative");
    }

    return true;
}
